/** static bool8 HandleMainMenuInput(u8 taskId) */
export function HandleMainMenuInput(taskId: any): any {
  let data: any = gTasks[taskId].data;

      if (JOY_NEW(A_BUTTON))
      {
          PlaySE(SE_SELECT);
          IsWirelessAdapterConnected();    
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_BLACK);
          gTasks[taskId].func = Task_HandleMainMenuAPressed;
      }
      else if (JOY_NEW(B_BUTTON))
      {
          PlaySE(SE_SELECT);
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 0x10, RGB_WHITEALPHA);
          SetGpuReg(REG_OFFSET_WIN0H, WIN_RANGE(0, DISPLAY_WIDTH));
          SetGpuReg(REG_OFFSET_WIN0V, WIN_RANGE(0, DISPLAY_HEIGHT));
          gTasks[taskId].func = Task_HandleMainMenuBPressed;
      }
      else if ((JOY_NEW(DPAD_UP)) && tCurrItem > 0)
      {
          if (tMenuType == HAS_MYSTERY_EVENTS && tIsScrolled == TRUE && tCurrItem == 1)
          {
              ChangeBgY(0, 0x2000, BG_COORD_SUB);
              ChangeBgY(1, 0x2000, BG_COORD_SUB);
              gTasks[tScrollArrowTaskId].tArrowTaskIsScrolled = tIsScrolled = FALSE;
          }
          tCurrItem--;
          sCurrItemAndOptionMenuCheck = tCurrItem;
          return TRUE;
      }
      else if ((JOY_NEW(DPAD_DOWN)) && tCurrItem < tItemCount - 1)
      {
          if (tMenuType == HAS_MYSTERY_EVENTS && tCurrItem == 3 && tIsScrolled == FALSE)
          {
              ChangeBgY(0, 0x2000, BG_COORD_ADD);
              ChangeBgY(1, 0x2000, BG_COORD_ADD);
              gTasks[tScrollArrowTaskId].tArrowTaskIsScrolled = tIsScrolled = TRUE;
          }
          tCurrItem++;
          sCurrItemAndOptionMenuCheck = tCurrItem;
          return TRUE;
      }
      return FALSE;
}

/** static void Task_HandleMainMenuInput(u8 taskId) */
export function Task_HandleMainMenuInput(taskId: any): any {
  if (HandleMainMenuInput(taskId))
          gTasks[taskId].func = Task_HighlightSelectedMainMenuItem;
}

/** static void Task_HandleMainMenuAPressed(u8 taskId) */
export function Task_HandleMainMenuAPressed(taskId: any): any {
  let wirelessAdapterConnected: any = null;
      let action: any = null;

      if (!gPaletteFade.active)
      {
          if (gTasks[taskId].tMenuType == HAS_MYSTERY_EVENTS)
              RemoveScrollIndicatorArrowPair(gTasks[taskId].tScrollArrowTaskId);
          ClearStdWindowAndFrame(0, TRUE);
          ClearStdWindowAndFrame(1, TRUE);
          ClearStdWindowAndFrame(2, TRUE);
          ClearStdWindowAndFrame(3, TRUE);
          ClearStdWindowAndFrame(4, TRUE);
          ClearStdWindowAndFrame(5, TRUE);
          ClearStdWindowAndFrame(6, TRUE);
          ClearStdWindowAndFrame(7, TRUE);
          wirelessAdapterConnected = IsWirelessAdapterConnected();
          switch (gTasks[taskId].tMenuType)
          {
              case HAS_NO_SAVED_GAME:
              default:
                  switch (gTasks[taskId].tCurrItem)
                  {
                      case 0:
                      default:
                          action = ACTION_NEW_GAME;
                          break;
                      case 1:
                          action = ACTION_OPTION;
                          break;
                  }
                  break;
              case HAS_SAVED_GAME:
                  switch (gTasks[taskId].tCurrItem)
                  {
                      case 0:
                      default:
                          action = ACTION_CONTINUE;
                          break;
                      case 1:
                          action = ACTION_NEW_GAME;
                          break;
                      case 2:
                          action = ACTION_OPTION;
                          break;
                  }
                  break;
              case HAS_MYSTERY_GIFT:
                  switch (gTasks[taskId].tCurrItem)
                  {
                      case 0:
                      default:
                          action = ACTION_CONTINUE;
                          break;
                      case 1:
                          action = ACTION_NEW_GAME;
                          break;
                      case 2:
                          action = ACTION_MYSTERY_GIFT;
                          if (!wirelessAdapterConnected)
                          {
                              action = ACTION_INVALID;
                              gTasks[taskId].tMenuType = HAS_NO_SAVED_GAME;
                          }
                          break;
                      case 3:
                          action = ACTION_OPTION;
                          break;
                  }
                  break;
              case HAS_MYSTERY_EVENTS:
                  switch (gTasks[taskId].tCurrItem)
                  {
                      case 0:
                      default:
                          action = ACTION_CONTINUE;
                          break;
                      case 1:
                          action = ACTION_NEW_GAME;
                          break;
                      case 2:
                          if (gTasks[taskId].tWirelessAdapterConnected)
                          {
                              action = ACTION_MYSTERY_GIFT;
                              if (!wirelessAdapterConnected)
                              {
                                  action = ACTION_INVALID;
                                  gTasks[taskId].tMenuType = HAS_NO_SAVED_GAME;
                              }
                          }
                          else if (wirelessAdapterConnected)
                          {
                              action = ACTION_INVALID;
                              gTasks[taskId].tMenuType = HAS_SAVED_GAME;
                          }
                          else
                          {
                              action = ACTION_EREADER;
                          }
                          break;
                      case 3:
                          if (wirelessAdapterConnected)
                          {
                              action = ACTION_INVALID;
                              gTasks[taskId].tMenuType = HAS_MYSTERY_GIFT;
                          }
                          else
                          {
                              action = ACTION_MYSTERY_EVENTS;
                          }
                          break;
                      case 4:
                          action = ACTION_OPTION;
                          break;
                  }
                  break;
          }
          ChangeBgY(0, 0, BG_COORD_SET);
          ChangeBgY(1, 0, BG_COORD_SET);
          switch (action)
          {
              case ACTION_NEW_GAME:
              default:
                  gPlttBufferUnfaded[0] = RGB_BLACK;
                  gPlttBufferFaded[0] = RGB_BLACK;
                  gTasks[taskId].func = Task_NewGameBirchSpeech_Init;
                  break;
              case ACTION_CONTINUE:
                  gPlttBufferUnfaded[0] = RGB_BLACK;
                  gPlttBufferFaded[0] = RGB_BLACK;
                  SetMainCallback2(CB2_ContinueSavedGame);
                  DestroyTask(taskId);
                  break;
              case ACTION_OPTION:
                  gMain.savedCallback = CB2_ReinitMainMenu;
                  SetMainCallback2(CB2_InitOptionMenu);
                  DestroyTask(taskId);
                  break;
              case ACTION_MYSTERY_GIFT:
                  SetMainCallback2(CB2_InitMysteryGift);
                  DestroyTask(taskId);
                  break;
              case ACTION_MYSTERY_EVENTS:
                  SetMainCallback2(CB2_InitMysteryEventMenu);
                  DestroyTask(taskId);
                  break;
              case ACTION_EREADER:
                  SetMainCallback2(CB2_InitEReader);
                  DestroyTask(taskId);
                  break;
              case ACTION_INVALID:
                  gTasks[taskId].tCurrItem = 0;
                  gTasks[taskId].func = Task_DisplayMainMenuInvalidActionError;
                  gPlttBufferUnfaded[BG_PLTT_ID(15) + 1] = RGB_WHITE;
                  gPlttBufferFaded[BG_PLTT_ID(15) + 1] = RGB_WHITE;
                  SetGpuReg(REG_OFFSET_BG2HOFS, 0);
                  SetGpuReg(REG_OFFSET_BG2VOFS, 0);
                  SetGpuReg(REG_OFFSET_BG1HOFS, 0);
                  SetGpuReg(REG_OFFSET_BG1VOFS, 0);
                  SetGpuReg(REG_OFFSET_BG0HOFS, 0);
                  SetGpuReg(REG_OFFSET_BG0VOFS, 0);
                  BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
                  return;
          }
          FreeAllWindowBuffers();
          if (action != ACTION_OPTION)
              sCurrItemAndOptionMenuCheck = 0;
          else
              sCurrItemAndOptionMenuCheck |= OPTION_MENU_FLAG;   
      }
}

