/** static void Task_NewGameBirchSpeechSub_InitPokeBall(u8 taskId) */
export function Task_NewGameBirchSpeechSub_InitPokeBall(taskId: any): any {
  let spriteId: any = gTasks[sBirchSpeechMainTaskId].tLotadSpriteId;

      gSprites[spriteId].x = 100;
      gSprites[spriteId].y = 75;
      gSprites[spriteId].invisible = FALSE;
      gSprites[spriteId].data[0] = 0;

      CreatePokeballSpriteToReleaseMon(spriteId, gSprites[spriteId].oam.paletteNum, 112, 58, 0, 0, 32, PALETTES_BG, SPECIES_LOTAD);
      gTasks[taskId].func = Task_NewGameBirchSpeechSub_WaitForLotad;
      gTasks[sBirchSpeechMainTaskId].tTimer = 0;
}

/** static void Task_NewGameBirchSpeechSub_WaitForLotad(u8 taskId) */
export function Task_NewGameBirchSpeechSub_WaitForLotad(taskId: any): any {
  let data: any = gTasks[taskId].data;
      let sprite: any =gSprites[gTasks[sBirchSpeechMainTaskId].tLotadSpriteId];

      switch (tState)
      {
          case 0:
              if (sprite.callback != SpriteCallbackDummy)
                  return;
              sprite.oam.affineMode = ST_OAM_AFFINE_OFF;
              break;
          case 1:
              if (gTasks[sBirchSpeechMainTaskId].tTimer >= 96)
              {
                  DestroyTask(taskId);
                  if (gTasks[sBirchSpeechMainTaskId].tTimer < 0x4000)
                      gTasks[sBirchSpeechMainTaskId].tTimer++;
              }
              return;
      }
      tState++;
      if (gTasks[sBirchSpeechMainTaskId].tTimer < 0x4000)
          gTasks[sBirchSpeechMainTaskId].tTimer++;
}

