/** static void Task_NewGameBirchSpeech_ChooseGender(u8 taskId) */
export function Task_NewGameBirchSpeech_ChooseGender(taskId: any): any {
  let gender: any = NewGameBirchSpeech_ProcessGenderMenuInput();
      let gender2: any = null;

      switch (gender)
      {
          case MALE:
              PlaySE(SE_SELECT);
              gSaveBlock2Ptr.playerGender = gender;
              NewGameBirchSpeech_ClearGenderWindow(1, 1);
              gTasks[taskId].func = Task_NewGameBirchSpeech_WhatsYourName;
              break;
          case FEMALE:
              PlaySE(SE_SELECT);
              gSaveBlock2Ptr.playerGender = gender;
              NewGameBirchSpeech_ClearGenderWindow(1, 1);
              gTasks[taskId].func = Task_NewGameBirchSpeech_WhatsYourName;
              break;
      }
      gender2 = Menu_GetCursorPos();
      if (gender2 != gTasks[taskId].tPlayerGender)
      {
          gTasks[taskId].tPlayerGender = gender2;
          gSprites[gTasks[taskId].tPlayerSpriteId].oam.objMode = ST_OAM_OBJ_BLEND;
          NewGameBirchSpeech_StartFadeOutTarget1InTarget2(taskId, 0);
          gTasks[taskId].func = Task_NewGameBirchSpeech_SlideOutOldGenderSprite;
      }
}

/** static void Task_NewGameBirchSpeech_SlideOutOldGenderSprite(u8 taskId) */
export function Task_NewGameBirchSpeech_SlideOutOldGenderSprite(taskId: any): any {
  let spriteId: any = gTasks[taskId].tPlayerSpriteId;
      if (gTasks[taskId].tIsDoneFadingSprites == 0)
      {
          gSprites[spriteId].x += 4;
      }
      else
      {
          gSprites[spriteId].invisible = TRUE;
          if (gTasks[taskId].tPlayerGender != MALE)
              spriteId = gTasks[taskId].tMaySpriteId;
          else
              spriteId = gTasks[taskId].tBrendanSpriteId;
          gSprites[spriteId].x = DISPLAY_WIDTH;
          gSprites[spriteId].y = 60;
          gSprites[spriteId].invisible = FALSE;
          gTasks[taskId].tPlayerSpriteId = spriteId;
          gSprites[spriteId].oam.objMode = ST_OAM_OBJ_BLEND;
          NewGameBirchSpeech_StartFadeInTarget1OutTarget2(taskId, 0);
          gTasks[taskId].func = Task_NewGameBirchSpeech_SlideInNewGenderSprite;
      }
}

/** static void Task_NewGameBirchSpeech_SlideInNewGenderSprite(u8 taskId) */
export function Task_NewGameBirchSpeech_SlideInNewGenderSprite(taskId: any): any {
  let spriteId: any = gTasks[taskId].tPlayerSpriteId;

      if (gSprites[spriteId].x > 180)
      {
          gSprites[spriteId].x -= 4;
      }
      else
      {
          gSprites[spriteId].x = 180;
          if (gTasks[taskId].tIsDoneFadingSprites)
          {
              gSprites[spriteId].oam.objMode = ST_OAM_OBJ_NORMAL;
              gTasks[taskId].func = Task_NewGameBirchSpeech_ChooseGender;
          }
      }
}

