/** static void Task_NewGameBirchSpeech_SlidePlatformAway2(u8 taskId) */
export function Task_NewGameBirchSpeech_SlidePlatformAway2(taskId: any): any {
  if (gTasks[taskId].tBG1HOFS)
      {
          gTasks[taskId].tBG1HOFS += 2;
          SetGpuReg(REG_OFFSET_BG1HOFS, gTasks[taskId].tBG1HOFS);
      }
      else
      {
          gTasks[taskId].func = Task_NewGameBirchSpeech_ReshowBirchLotad;
      }
}

/** static void Task_NewGameBirchSpeech_ReshowBirchLotad(u8 taskId) */
export function Task_NewGameBirchSpeech_ReshowBirchLotad(taskId: any): any {
  let spriteId: any = null;

      if (gTasks[taskId].tIsDoneFadingSprites)
      {
          gSprites[gTasks[taskId].tBrendanSpriteId].invisible = TRUE;
          gSprites[gTasks[taskId].tMaySpriteId].invisible = TRUE;
          spriteId = gTasks[taskId].tBirchSpriteId;
          gSprites[spriteId].x = 136;
          gSprites[spriteId].y = 60;
          gSprites[spriteId].invisible = FALSE;
          gSprites[spriteId].oam.objMode = ST_OAM_OBJ_BLEND;
          spriteId = gTasks[taskId].tLotadSpriteId;
          gSprites[spriteId].x = 100;
          gSprites[spriteId].y = 75;
          gSprites[spriteId].invisible = FALSE;
          gSprites[spriteId].oam.objMode = ST_OAM_OBJ_BLEND;
          NewGameBirchSpeech_StartFadeInTarget1OutTarget2(taskId, 2);
          NewGameBirchSpeech_StartFadePlatformOut(taskId, 1);
          NewGameBirchSpeech_ClearWindow(0);
          StringExpandPlaceholders(gStringVar4, gText_Birch_YourePlayer);
          AddTextPrinterForMessage(TRUE);
          gTasks[taskId].func = Task_NewGameBirchSpeech_WaitForSpriteFadeInAndTextPrinter;
      }
}

/** static void Task_NewGameBirchSpeech_WaitForSpriteFadeInAndTextPrinter(u8 taskId) */
export function Task_NewGameBirchSpeech_WaitForSpriteFadeInAndTextPrinter(taskId: any): any {
  if (gTasks[taskId].tIsDoneFadingSprites)
      {
          gSprites[gTasks[taskId].tBirchSpriteId].oam.objMode = ST_OAM_OBJ_NORMAL;
          gSprites[gTasks[taskId].tLotadSpriteId].oam.objMode = ST_OAM_OBJ_NORMAL;
          if (!RunTextPrintersAndIsPrinter0Active())
          {
              gSprites[gTasks[taskId].tBirchSpriteId].oam.objMode = ST_OAM_OBJ_BLEND;
              gSprites[gTasks[taskId].tLotadSpriteId].oam.objMode = ST_OAM_OBJ_BLEND;
              NewGameBirchSpeech_StartFadeOutTarget1InTarget2(taskId, 2);
              NewGameBirchSpeech_StartFadePlatformIn(taskId, 1);
              gTasks[taskId].tTimer = 64;
              gTasks[taskId].func = Task_NewGameBirchSpeech_AreYouReady;
          }
      }
}

/** static void Task_NewGameBirchSpeech_AreYouReady(u8 taskId) */
export function Task_NewGameBirchSpeech_AreYouReady(taskId: any): any {
  let spriteId: any = null;

      if (gTasks[taskId].tIsDoneFadingSprites)
      {
          gSprites[gTasks[taskId].tBirchSpriteId].invisible = TRUE;
          gSprites[gTasks[taskId].tLotadSpriteId].invisible = TRUE;
          if (gTasks[taskId].tTimer)
          {
              gTasks[taskId].tTimer--;
              return;
          }
          if (gSaveBlock2Ptr.playerGender != MALE)
              spriteId = gTasks[taskId].tMaySpriteId;
          else
              spriteId = gTasks[taskId].tBrendanSpriteId;
          gSprites[spriteId].x = 120;
          gSprites[spriteId].y = 60;
          gSprites[spriteId].invisible = FALSE;
          gSprites[spriteId].oam.objMode = ST_OAM_OBJ_BLEND;
          gTasks[taskId].tPlayerSpriteId = spriteId;
          NewGameBirchSpeech_StartFadeInTarget1OutTarget2(taskId, 2);
          NewGameBirchSpeech_StartFadePlatformOut(taskId, 1);
          StringExpandPlaceholders(gStringVar4, gText_Birch_AreYouReady);
          AddTextPrinterForMessage(TRUE);
          gTasks[taskId].func = Task_NewGameBirchSpeech_ShrinkPlayer;
      }
}

/** static void Task_NewGameBirchSpeech_ShrinkPlayer(u8 taskId) */
export function Task_NewGameBirchSpeech_ShrinkPlayer(taskId: any): any {
  let spriteId: any = null;

      if (gTasks[taskId].tIsDoneFadingSprites)
      {
          gSprites[gTasks[taskId].tPlayerSpriteId].oam.objMode = ST_OAM_OBJ_NORMAL;
          if (!RunTextPrintersAndIsPrinter0Active())
          {
              spriteId = gTasks[taskId].tPlayerSpriteId;
              gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_NORMAL;
              gSprites[spriteId].affineAnims = sSpriteAffineAnimTable_PlayerShrink;
              InitSpriteAffineAnim(gSprites[spriteId]);
              StartSpriteAffineAnim(gSprites[spriteId], 0);
              gSprites[spriteId].callback = SpriteCB_MovePlayerDownWhileShrinking;
              BeginNormalPaletteFade(PALETTES_BG, 0, 0, 16, RGB_BLACK);
              FadeOutBGM(4);
              gTasks[taskId].func = Task_NewGameBirchSpeech_WaitForPlayerShrink;
          }
      }
}

/** static void Task_NewGameBirchSpeech_WaitForPlayerShrink(u8 taskId) */
