/** static void CB2_NewGameBirchSpeech_ReturnFromNamingScreen(void) */
export function CB2_NewGameBirchSpeech_ReturnFromNamingScreen(): any {
  let taskId: any = null;
      let spriteId: any = null;
      let savedIme: any = null;

      ResetBgsAndClearDma3BusyFlags(0);
      SetGpuReg(REG_OFFSET_DISPCNT, 0);
      SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_OBJ_1D_MAP);
      InitBgsFromTemplates(0, sMainMenuBgTemplates, ARRAY_COUNT(sMainMenuBgTemplates));
      InitBgFromTemplate(sBirchBgTemplate);
      SetVBlankCallback(NULL);
      SetGpuReg(REG_OFFSET_BG2CNT, 0);
      SetGpuReg(REG_OFFSET_BG1CNT, 0);
      SetGpuReg(REG_OFFSET_BG0CNT, 0);
      SetGpuReg(REG_OFFSET_BG2HOFS, 0);
      SetGpuReg(REG_OFFSET_BG2VOFS, 0);
      SetGpuReg(REG_OFFSET_BG1HOFS, 0);
      SetGpuReg(REG_OFFSET_BG1VOFS, 0);
      SetGpuReg(REG_OFFSET_BG0HOFS, 0);
      SetGpuReg(REG_OFFSET_BG0VOFS, 0);
      DmaFill16(3, 0, VRAM, VRAM_SIZE);
      DmaFill32(3, 0, OAM, OAM_SIZE);
      DmaFill16(3, 0, PLTT, PLTT_SIZE);
      ResetPaletteFade();
      LZ77UnCompVram(sBirchSpeechShadowGfx, VRAM);
      LZ77UnCompVram(sBirchSpeechBgMap, (BG_SCREEN_ADDR(7)));
      LoadPalette(sBirchSpeechBgPals, BG_PLTT_ID(0), 2 * PLTT_SIZE_4BPP);
      LoadPalette(sBirchSpeechBgGradientPal[1], BG_PLTT_ID(0) + 1, PLTT_SIZEOF(8));
      ResetTasks();
      taskId = CreateTask(Task_NewGameBirchSpeech_ReturnFromNamingScreenShowTextbox, 0);
      gTasks[taskId].tTimer = 5;
      gTasks[taskId].tBG1HOFS = -60;
      ScanlineEffect_Stop();
      ResetSpriteData();
      FreeAllSpritePalettes();
      ResetAllPicSprites();
      AddBirchSpeechObjects(taskId);
      if (gSaveBlock2Ptr.playerGender != MALE)
      {
          gTasks[taskId].tPlayerGender = FEMALE;
          spriteId = gTasks[taskId].tMaySpriteId;
      }
      else
      {
          gTasks[taskId].tPlayerGender = MALE;
          spriteId = gTasks[taskId].tBrendanSpriteId;
      }
      gSprites[spriteId].x = 180;
      gSprites[spriteId].y = 60;
      gSprites[spriteId].invisible = FALSE;
      gTasks[taskId].tPlayerSpriteId = spriteId;
      SetGpuReg(REG_OFFSET_BG1HOFS, -60);
      BeginNormalPaletteFade(PALETTES_ALL, 0, 16, 0, RGB_BLACK);
      SetGpuReg(REG_OFFSET_WIN0H, 0);
      SetGpuReg(REG_OFFSET_WIN0V, 0);
      SetGpuReg(REG_OFFSET_WININ, 0);
      SetGpuReg(REG_OFFSET_WINOUT, 0);
      SetGpuReg(REG_OFFSET_BLDCNT, 0);
      SetGpuReg(REG_OFFSET_BLDALPHA, 0);
      SetGpuReg(REG_OFFSET_BLDY, 0);
      ShowBg(0);
      ShowBg(1);
      savedIme = REG_IME;
      REG_IME = 0;
      REG_IE |= 1;
      REG_IME = savedIme;
      SetVBlankCallback(VBlankCB_MainMenu);
      SetMainCallback2(CB2_MainMenu);
      InitWindows(sNewGameBirchSpeechTextWindows);
      LoadMainMenuWindowFrameTiles(0, 0xF3);
      LoadMessageBoxGfx(0, BIRCH_DLG_BASE_TILE_NUM, BG_PLTT_ID(15));
      PutWindowTilemap(0);
      CopyWindowToVram(0, COPYWIN_FULL);
}

/** static void SpriteCB_MovePlayerDownWhileShrinking(struct Sprite *sprite) */
export function SpriteCB_MovePlayerDownWhileShrinking(sprite: any): any {
  let y: any = null;

      y = (sprite.y << 16) + sprite.data[0] + 0xC000;
      sprite.y = y >> 16;
      sprite.data[0] = y;
}

