export function NewGameBirchSpeech_ClearGenderWindowTilemap(bg: any, x: any, y: any, width: any, height: any, unused: any): any {
  FillBgTilemapBufferRect(bg, 0, x + 255, y + 255, width + 2, height + 2, 2);
}

/** static void NewGameBirchSpeech_ClearGenderWindow(u8 windowId, bool8 copyToVram) */
export function NewGameBirchSpeech_ClearGenderWindow(windowId: any, copyToVram: any): any {
  CallWindowFunction(windowId, NewGameBirchSpeech_ClearGenderWindowTilemap);
      FillWindowPixelBuffer(windowId, PIXEL_FILL(1));
      ClearWindowTilemap(windowId);
      if (copyToVram == TRUE)
          CopyWindowToVram(windowId, COPYWIN_FULL);
}

/** static void NewGameBirchSpeech_ClearWindow(u8 windowId) */
export function NewGameBirchSpeech_ClearWindow(windowId: any): any {
  let bgColor: any = GetFontAttribute(FONT_NORMAL, FONTATTR_COLOR_BACKGROUND);
      let maxCharWidth: any = GetFontAttribute(FONT_NORMAL, FONTATTR_MAX_LETTER_WIDTH);
      let maxCharHeight: any = GetFontAttribute(FONT_NORMAL, FONTATTR_MAX_LETTER_HEIGHT);
      let winWidth: any = GetWindowAttribute(windowId, WINDOW_WIDTH);
      let winHeight: any = GetWindowAttribute(windowId, WINDOW_HEIGHT);

      FillWindowPixelRect(windowId, bgColor, 0, 0, maxCharWidth * winWidth, maxCharHeight * winHeight);
      CopyWindowToVram(windowId, COPYWIN_GFX);
}

/** static void NewGameBirchSpeech_WaitForThisIsPokemonText(struct TextPrinterTemplate *printer, u16 renderCmd) */
export function NewGameBirchSpeech_WaitForThisIsPokemonText(printer: any, renderCmd: any): any {
  if ((printer.currentChar - 2) == EXT_CTRL_CODE_PAUSE && !sStartedPokeBallTask)
      {
          sStartedPokeBallTask = TRUE;
          CreateTask(Task_NewGameBirchSpeechSub_InitPokeBall, 0);
      }
}

/** void CreateYesNoMenuParameterized(u8 x, u8 y, u16 baseTileNum, u16 baseBlock, u8 yesNoPalNum, u8 winPalNum) */
export function CreateYesNoMenuParameterized(x: any, y: any, baseTileNum: any, baseBlock: any, yesNoPalNum: any, winPalNum: any): any {
  let template: any = CreateWindowTemplate(0, x + 1, y + 1, 5, 4, winPalNum, baseBlock);
      CreateYesNoMenu(template, baseTileNum, yesNoPalNum, 0);
}

